import{_ as o,o as i,c as t,ao as n}from"./chunks/framework.DHldJ08f.js";const g=JSON.parse('{"title":"Sign in with Google","description":"","frontmatter":{"prev":false,"next":false,"title":"Sign in with Google"},"headers":[],"relativePath":"guides/sign-in-with-google.md","filePath":"guides/sign-in-with-google.md"}'),a={name:"guides/sign-in-with-google.md"};function r(s,e,l,h,d,p){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="sign-in-with-google-in-open-grind" tabindex="-1">Sign in with Google in Open Grind <a class="header-anchor" href="#sign-in-with-google-in-open-grind" aria-label="Permalink to “Sign in with Google in Open Grind”">​</a></h1><p>Starting with v0.1.0-beta.2 it&#39;s possible to authenticate if your account in Grindr was created with Google.</p><h2 id="windows-linux-macos-ios" tabindex="-1">Windows, Linux, macOS, iOS <a class="header-anchor" href="#windows-linux-macos-ios" aria-label="Permalink to “Windows, Linux, macOS, iOS”">​</a></h2><p>Just download the app and tap &quot;Sign in with Google&quot; on the sign-in screen.</p><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to “Android”">​</a></h2><p>Due to security checks by Google, you must <a href="#open-grind-google-oauth-app-recommended">install a Google OAuth add-on (recommended)</a> or <a href="#manually-paste-google-oauth-token">paste the sign in token manually</a>.</p><h3 id="open-grind-google-oauth-app-recommended" tabindex="-1">Open Grind Google OAuth app (recommended) <a class="header-anchor" href="#open-grind-google-oauth-app-recommended" aria-label="Permalink to “Open Grind Google OAuth app (recommended)”">​</a></h3><ol><li>Tap &quot;Sign in with Google&quot;</li><li>On the sign in screen, tap &quot;Install&quot; and confirm Android&#39;s install prompt; alternatively, install <a href="https://git.opengrind.org/open-grind/google-oauth-app/releases" target="_blank" rel="noreferrer">Google OAuth App manually</a></li><li>Tap &quot;Continue&quot;, then follow the instructions</li></ol><h3 id="installed-from-google-play" tabindex="-1">Installed from Google Play <a class="header-anchor" href="#installed-from-google-play" aria-label="Permalink to “Installed from Google Play”">​</a></h3><p>Open Grind from Google Play can&#39;t install other apps, so install the add-on yourself:</p><ol><li>Open <a href="https://git.opengrind.org/open-grind/google-oauth-app/releases" target="_blank" rel="noreferrer">Google OAuth App releases</a> in your browser</li><li>Download the APK for your device and open it; Android asks your browser for permission to install apps once</li><li>Return to Open Grind, tap &quot;Sign in with Google&quot;, then &quot;Continue&quot;</li></ol><p>Or skip the add-on and <a href="#manually-paste-google-oauth-token">paste the sign in token manually</a>.</p><h3 id="manually-paste-google-oauth-token" tabindex="-1">Manually paste Google OAuth token <a class="header-anchor" href="#manually-paste-google-oauth-token" aria-label="Permalink to “Manually paste Google OAuth token”">​</a></h3><p><strong>If you already have Open Grind Google OAuth app installed,</strong> try these steps to retrieve Google OAuth token and put it into Open Grind manually:</p><ol><li>Launch <strong>Open Grind Google OAuth</strong> app from your Android launcher or home</li><li>Tap the &quot;Sign in with Google&quot; button, then follow the instructions to sign in</li><li>You land on a page with your token masked. Tap &quot;Copy token&quot;</li><li>Go to Open Grind sign in with Google screen and tap &quot;paste the OAuth token manually&quot;</li><li>Paste the copied token and tap &quot;Sign in&quot;</li></ol><p><strong>If you have Firefox or Librewolf installed (Desktop/Android), Google Chrome or Chromium-based browsers (Desktop only, there are no extensions in Google Chrome for Android),</strong> you have an option to avoid using the Google OAuth app altogether.</p><ol><li>Install the <a href="https://git.opengrind.org/open-grind/grindr-google-oauth-webextension#install" target="_blank" rel="noreferrer"><strong>Grindr Google OAuth WebExtension</strong></a> in your browser</li><li>In the extensions list in the browser toolbar, click on the <strong>extension&#39;s icon</strong></li><li>A new page should open with the &quot;Sign in with Google&quot; button — tap it, then follow the instructions to sign in</li><li>You land on a page with your token masked. Tap &quot;Copy token&quot;</li><li>Go to Open Grind sign in with Google screen and tap &quot;paste the OAuth token manually&quot;</li><li>Paste the copied token and tap &quot;Sign in&quot;</li></ol><h3 id="why-a-separate-app-technical-in-depth-explanation" tabindex="-1">Why a separate app? (technical in-depth explanation) <a class="header-anchor" href="#why-a-separate-app-technical-in-depth-explanation" aria-label="Permalink to “Why a separate app? (technical in-depth explanation)”">​</a></h3><p>This section answers some questions on why the decision to release a separate Google OAuth app for Android was made. It&#39;s intended for technical experts who have some knowledge of mobile development and are familiar with the OAuth protocol.</p><p><em>Full discussion: <a href="https://git.opengrind.org/open-grind/open-grind/issues/27" target="_blank" rel="noreferrer">https://git.opengrind.org/open-grind/open-grind/issues/27</a></em></p><h4 id="why-not-the-native-google-oauth-flow" tabindex="-1">Why not the native Google OAuth flow? <a class="header-anchor" href="#why-not-the-native-google-oauth-flow" aria-label="Permalink to “Why not the native Google OAuth flow?”">​</a></h4><p>The official Grindr app uses Google Identity Services installed on the Android device to authenticate user. This means the app calls host system&#39;s GIS, which checks both caller package id (which must be <code>com.grindrapp.android</code> and not <code>org.opengrind</code>, and setting latter to former would cause conflict errors for users who use both) and, more importantly, package signature (which is not possible to forge, since we don&#39;t hold Grindr&#39;s JKS; signature spoofing is only possible on some ROMs and rooted devices).</p><p><strong>There is no way to launch native Google OAuth flow for Grindr&#39;s official app from a third-party client using the official Google Play Services.</strong></p><h4 id="why-not-use-microg-or-another-free-reimplementation" tabindex="-1">Why not use microG or another free reimplementation? <a class="header-anchor" href="#why-not-use-microg-or-another-free-reimplementation" aria-label="Permalink to “Why not use microG or another free reimplementation?”">​</a></h4><p>MicroG itself does not allow spoofing, as it&#39;s a drop-in that works via the same APIs. YouTube ReVanced ships its own patched microG. However there&#39;s still a problem: native Google OAuth flow requires a DroidGuard token, which is obtained by executing a proprietary opaque blob generated by Google web API per-request inside of a proprietary opaque attestation VM requiring permissions to the device to validate it&#39;s a real physical device and not an emulator. DroidGuard VMs are completely obfuscated and reverse engineering attempts by microG developers failed. <a href="https://github.com/microg/GmsCore/issues/214#issuecomment-2040272095" target="_blank" rel="noreferrer">See microG discussion</a>.</p><p><strong>There is no way to complete native Google OAuth flow without having a real physical Android device and running proprietary opaque executables from Google.</strong> This defeats both cross-platform goal of Open Grind and full transparency.</p><h4 id="can-we-authenticate-user-with-google-oauth-without-native-flow" tabindex="-1">Can we authenticate user with Google OAuth without native flow? <a class="header-anchor" href="#can-we-authenticate-user-with-google-oauth-without-native-flow" aria-label="Permalink to “Can we authenticate user with Google OAuth without native flow?”">​</a></h4><p>Yes, that&#39;s how web.grindr.com works. The entire authentication is web flow, meaning it&#39;s supposed to run in browsers, without requiring any device attestation tokens, so it&#39;s possible to run it on any platform, even in emulators. Web flow is launched from web.grindr.com with <code>responseType=postMessage</code> and the resulting code is posted by GIS JavaScript with <code>web.grindr.com</code> origin, so only pages with web.grindr.com origin can receive the callback. Additionally, browsers (even embedded ones) prevent actions such as opening new tabs without user gesture, which is why a tap is needed on the launch page.</p><p>However, there&#39;s another problem: Google OAuth Web Flow page checks aggressively for any signs of rendering the sign-in page in embedded windows (including system WebViews, which is what Tauri uses under the hood of Open Grind UI), and while changing User-Agent and removing Sec- headers is possible for both WebKit-based WebViews (WKWebView for macOS &amp; iOS, WebKitGTK for Linux) and Chromium-based WebViews (WebView2 for Windows, Chromium for Android), <strong>Android&#39;s Chromium WebView specifically adds a special X-Requested-With header that&#39;s impossible to remove.</strong> This has been pushed by Google specifically for &quot;fraud/abuse detection&quot; (i.e. to detect Android WebView in their services, such as the OAuth page). In 2023 it was announced Google starts a trial to allow developers to opt-out of sending this header, <strong>but in 2025 the decision was reversed and X-Requested-With is now sent on all Android system&#39;s Chromium WebView requests with no option to disable it,</strong> which is exactly what triggers Google OAuth page &quot;security checks&quot; and rejects attempts to sign in.</p><p><strong>All other platforms work just fine by rendering Google&#39;s OAuth page directly in platform&#39;s native WebView,</strong> so it&#39;s only an issue on Android.</p><h4 id="can-we-bundle-a-different-webview-for-android" tabindex="-1">Can we bundle a different WebView for Android? <a class="header-anchor" href="#can-we-bundle-a-different-webview-for-android" aria-label="Permalink to “Can we bundle a different WebView for Android?”">​</a></h4><p>There aren&#39;t many choices: for Android only Chromium WebView and Mozilla&#39;s GeckoView are available. While it&#39;s possible to bundle one with the Open Grind app, there are two practical concerns:</p><ol><li>WebView libraries are massive. Chromium is 200+ MB, GeckoView is slightly lighter being ~100 MB.</li><li>Many users won&#39;t even need to ever sign in with Google, so adding 100MB+ to app size just to render one page isn&#39;t practical.</li><li>Additionally, publishing an app to F-Droid&#39;s official repository requires building every dependency from source, and building GeckoView takes hours even on powerful machines — this is why you <a href="https://forum.f-droid.org/t/clean-build-with-geckoview-dependency/11066" target="_blank" rel="noreferrer">don&#39;t see any apps with GeckoView in the F-Droid repository</a> (except for browsers such as Fennec and Tor); also GeckoView includes Google Services, so we&#39;d have to patch it before building from source</li></ol><p><strong>Each CPU architecture adds ~100MB to the universal bundle. So Open Grind apk grows from ~70MB to ~500MB just for one page used once only by some people.</strong></p><h4 id="can-we-bundle-geckoview-with-android-app-and-render-the-app-itself-in-it" tabindex="-1">Can we bundle GeckoView with Android app and render the app itself in it? <a class="header-anchor" href="#can-we-bundle-geckoview-with-android-app-and-render-the-app-itself-in-it" aria-label="Permalink to “Can we bundle GeckoView with Android app and render the app itself in it?”">​</a></h4><p>No, Tauri&#39;s <a href="https://github.com/tauri-apps/wry" target="_blank" rel="noreferrer">wry</a> only works with system&#39;s WebView (i.e., Chromium).</p><h4 id="how-do-we-solve-all-these-issues" tabindex="-1">How do we solve all these issues? <a class="header-anchor" href="#how-do-we-solve-all-these-issues" aria-label="Permalink to “How do we solve all these issues?”">​</a></h4><p>To solve these Google OAuth issues, we&#39;ve built the <a href="https://git.opengrind.org/open-grind/grindr-google-oauth-webextension" target="_blank" rel="noreferrer">Grindr Google OAuth WebExtension</a>. It&#39;s a browser extension (Firefox, any Firefox-based browser such as Librewolf, Firefox for Android, Google Chrome, Chromium, any Chromium-based browser such as Brave) that launches web.grindr.com (to satisfy the launch page&#39;s origin requirement), replaces document with a simple &quot;Sign in with Google&quot; button, then intercepts the response token from Google OAuth page before it hits Grindr Web&#39;s API and either shows it masked on a local page for copying, or passes it to GeckoView for programmatic intent.</p><h4 id="so-why-build-an-app-if-it-s-an-extension" tabindex="-1">So why build an app if it&#39;s an extension? <a class="header-anchor" href="#so-why-build-an-app-if-it-s-an-extension" aria-label="Permalink to “So why build an app if it&#39;s an extension?”">​</a></h4><p>The whole app is basically a headless browser powered by <a href="https://mozilla.github.io/geckoview/" target="_blank" rel="noreferrer">GeckoView</a> embedding the extension. The reason is simply that most Android users don&#39;t have Firefox and use Google Chrome for Android instead, which does not support extensions.</p><p>Also, the app features a programmatic intent, which allows the Open Grind app to call this app and get the token back automatically without copy-pasting. For security, this only works with official builds: Open Grind must be signed by Open Grind or installed from Google Play, and the Google OAuth app must be signed by Open Grind.</p><p>If you&#39;re an <em>advanced user</em> and prefer to avoid installing an unnecessary app, consider using the browser extension directly and copy-pasting the token into Open Grind app.</p>',42)])])}const c=o(a,[["render",r]]);export{g as __pageData,c as default};
